#!/usr/bin/env bash
# Run the Airtest flow and produce the two artefacts a reviewer opens:
#   out/airtest-report/log.html   steps, screenshots, one row per action
#   out/airtest-report/*.mp4      screen recording of the same run
# The log.html is generated by `airtest report`, not by `airtest run` — run only
# writes log.txt + screenshots.
set -euo pipefail
pkg="${1:?usage: run_flow.sh <package> [serial]}"
serial="${2:-}"
device_uri="Android:///${serial}"

log_dir="out/airtest"
target="out/airtest-report"
rm -rf "$log_dir" "$target"
mkdir -p "$log_dir"

echo "[1/3] airtest run (this is where log.txt, screenshots and the mp4 come from)"
SLOT_PACKAGE="$pkg" airtest run flows/slot_smoke.py --device "$device_uri" --log "$log_dir" --recording

log_root="$(dirname "$(find "$log_dir" -name log.txt -print -quit)")"
echo "[2/3] airtest report -> $target/log.html"
airtest report flows/slot_smoke.py --log_root "$log_root" --outfile "$target/log.html" --lang en \
  --export "$target"

echo "[3/3] recording"
find "$target" -name '*.mp4' -print | sed 's/^/  /' || true

echo
echo "open:      $target/log.html"
echo "portable:  the whole $target directory (log.html links its own images and video)"
